<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { getResourceCatalog } from '../api/modules/resources'; import type { MapDefinition } from '../types/domain'; const maps=ref<MapDefinition[]>([]); const router=useRouter(); onMounted(async()=>{maps.value=(await getResourceCatalog()).maps})</script>
